1	// pattern: Functional Core (one shared network core + a neutral error, no Tauri state)
2	//
3	// Both wallet source-login paths — the claim flow (`claim::authenticate_source_pds`) and the
4	// outbound migration (`migration_orchestrator::authenticate_migration_source`) — open a full
5	// session against the account's *current* PDS with a password `createSession` and wrap it in a
6	// Bearer `OAuthClient` (ADR-0021). A spec-strict PDS (bsky.social) gates the
7	// operations that follow — PLC/identity ops for the claim, minting the source's
8	// `com.atproto.server.createAccount` service-auth token for the migration — behind a full session;
9	// the atproto OAuth ceiling for a third-party client is `transition:generic`, which those
10	// operations refuse.
11	//
12	// The body is identical apart from which frontend-facing error enum it feeds. This module owns
13	// that body once and returns a neutral `SourceLoginError`; each caller keeps its own public enum
14	// and maps `SourceLoginError` in via `From`. Two distinct enums are a deliberate design
15	// choice — the goal is to share the *behavior + tests*, not collapse the contracts.
16	
17	use crate::oauth_client::OAuthClient;
18	
19	/// Neutral result of a source-PDS password login, mapped into each caller's frontend-facing error
20	/// enum (`ClaimError` / `MigrationError`) via `From`. The variants mirror exactly the ones both
21	/// callers used to produce inline, so the mapping is total and lossless.
22	#[derive(Debug)]
23	pub(crate) enum SourceLoginError {
24	    /// The account has email two-factor enabled: `createSession` returned `AuthFactorTokenRequired`
25	    /// and the PDS emailed a one-time code. The UI prompts for the code and re-invokes with it.
26	    TwoFactorRequired,
27	    /// The source PDS rejected the password (`createSession` 401). `message` is a fixed,
28	    /// user-safe string — never the server's raw text — so the UI can say "wrong password".
29	    SourceAuthFailed { message: String },
30	    /// The session the PDS returned is for a different account than the one being claimed/migrated.
31	    AccountMismatch,
32	    /// Refused to send the password to a non-HTTPS, non-loopback source PDS (endpoint from the DID
33	    /// document).
34	    InsecureSourceUrl,
35	    /// The source PDS rate-limited the login (HTTP 429). `retry_after` carries `Retry-After`.
36	    RateLimited { retry_after: Option<String> },
37	    /// A non-2xx the wallet doesn't model specially. `message` is the server's own error text.
38	    ServerError { message: String },
39	    /// Transport failure, or the returned session couldn't be turned into a Bearer client.
40	    NetworkError { message: String },
41	}
42	
43	/// Shared core: run `createSession` against the source PDS and build a full-session Bearer
44	/// `OAuthClient`, enforcing the account-match guard. Extracted so both source-login paths share one
45	/// implementation and one behavioral test suite.
46	///
47	/// `expected_did` is the DID being claimed/migrated: the session the PDS returns MUST be for that
48	/// account, or the caller signed in to the wrong one and we refuse to bind those credentials rather
49	/// than act against the wrong identity. The password is used for one request and never stored.
50	pub(crate) async fn authenticate_source_password(
51	    pds_client: &crate::pds_client::PdsClient,
52	    pds_url: &str,
53	    expected_did: &str,
54	    identifier: &str,
55	    password: &str,
56	    auth_factor_token: Option<&str>,
57	) -> Result<OAuthClient, SourceLoginError> {
58	    let session = pds_client
59	        .create_session(pds_url, identifier, password, auth_factor_token)
60	        .await
61	        .map_err(|e| match e {
62	            crate::pds_client::PdsClientError::AuthFactorTokenRequired => {
63	                tracing::info!("source account has email 2FA; a code was sent");
64	                SourceLoginError::TwoFactorRequired
65	            }
66	            crate::pds_client::PdsClientError::InvalidCredentials { message } => {
67	                tracing::warn!(detail = %message, "source createSession rejected the password");
68	                SourceLoginError::SourceAuthFailed {
69	                    message: "The PDS did not accept that password.".to_string(),
70	                }
71	            }
72	            crate::pds_client::PdsClientError::InsecurePdsUrl { url } => {
73	                tracing::error!(pds_url = %url, "refusing password login to a non-HTTPS PDS");
74	                SourceLoginError::InsecureSourceUrl
75	            }
76	            // A rate limit or other server rejection during the password login must keep its real
77	            // reason too — a 429 here is not a connectivity problem.
78	            crate::pds_client::PdsClientError::RateLimited { retry_after, .. } => {
79	                SourceLoginError::RateLimited { retry_after }
80	            }
81	            crate::pds_client::PdsClientError::XrpcError { message, .. } => {
82	                SourceLoginError::ServerError { message }
83	            }
84	            other => SourceLoginError::NetworkError {
85	                message: format!("createSession failed: {}", other),
86	            },
87	        })?;
88	
89	    // The session must be for the account being claimed/migrated. A mismatch means the user signed
90	    // in to a different account (or a hostile PDS returned someone else's session) — refuse to bind
91	    // those credentials rather than act against the wrong identity.
92	    if session.did != expected_did {
93	        tracing::warn!(
94	            expected = %expected_did,
95	            got = %session.did,
96	            "source session DID does not match the expected identity"
97	        );
98	        return Err(SourceLoginError::AccountMismatch);
99	    }
100	
101	    OAuthClient::new_bearer(session.access_jwt, session.refresh_jwt, pds_url.to_string()).map_err(
102	        |e| {
103	            tracing::error!(error = %e, "failed to build Bearer client from source session");
104	            SourceLoginError::NetworkError {
105	                message: "failed to build source session client".to_string(),
106	            }
107	        },
108	    )
109	}
