115	    /// Build a Bearer-session JWT with a future `exp` so `new_bearer` derives a live expiry.
116	    fn future_exp_jwt() -> String {
117	        use base64::engine::general_purpose::URL_SAFE_NO_PAD;
118	        use base64::Engine;
119	        let now = std::time::SystemTime::now()
120	            .duration_since(std::time::UNIX_EPOCH)
121	            .unwrap()
122	            .as_secs();
123	        let header = URL_SAFE_NO_PAD.encode(r#"{"alg":"ES256"}"#);
124	        let payload = URL_SAFE_NO_PAD.encode(format!(r#"{{"exp":{}}}"#, now + 3600).as_bytes());
125	        format!("{}.{}.sig", header, payload)
126	    }
