1	// pattern: Imperative Shell
2	//
3	// Gathers: the `custos` extension of a host's describeServer response
4	// Processes: normalizes the host key and answers capability questions
5	// Returns: a per-host capability set, cached for the process lifetime
6	
7	//! What the identity's host can do, cached per host.
8	//!
9	//! Obsign works against any spec-compliant PDS. Most of what it offers — the claim
10	//! ceremony, PLC monitoring, the recovery override, repo and media backup, endpoint
11	//! repair — is standard AT Protocol and needs nothing from the host but conformance. A
12	//! smaller set of features needs Custos, and until now the wallet discovered that by
13	//! calling a `/v1/*` route and interpreting the failure, which cannot distinguish "this
14	//! host does not offer that" from "that host is having a bad day".
15	//!
16	//! Custos answers the question directly: `com.atproto.server.describeServer` carries a
17	//! `custos` object naming the capabilities that deployment actually offers. This module
18	//! is the wallet's reader for it.
19	//!
20	//! **Absence is not an error.** The reference PDS and rsky-pds return strictly the
21	//! lexicon fields; millipds adds a top-level `version` with unrelated semantics. A
22	//! response with no `custos` object yields [`ServerCapabilities::none`] — no capabilities,
23	//! standard-lexicon behavior — which is the correct reading for every implementation that
24	//! is not Custos, and for a Custos deployment running with a capability switched off.
25	//!
26	//! **A gate reads as a feature question, never a vendor question.** There is deliberately
27	//! no `is_custos()`: a self-hosted Custos may run without escrow, and a future
28	//! implementation could adopt a single capability. Ask [`ServerCapabilities::has`].
29	
30	use std::collections::HashMap;
31	use std::sync::{Mutex, OnceLock};
32	
33	use serde::Serialize;
34	
35	use crate::pds_client::{CustosExtension, PdsClient};
36	
37	/// The capability names Custos advertises. Wire contract — these strings are matched
38	/// verbatim against `custos.capabilities`, and the server's `crates/pds/src/capabilities.rs`
39	/// is their source of truth.
40	pub mod capability {
41	    /// Custos-native identity creation (mobile signup + client-authored did:plc genesis).
42	    pub const CREATE_CEREMONY: &str = "createCeremony";
43	    /// Server-held encrypted Shamir Share 2, released through the recovery gate.
44	    pub const ESCROW: &str = "escrow";
45	    /// Passwordless full-access sessions from a rotation-key-signed proof.
46	    pub const SOVEREIGN_SESSIONS: &str = "sovereignSessions";
47	    /// The auth.md agent registration + owner-confirmed claim ceremony.
48	    pub const AGENTS: &str = "agents";
49	    /// Device-key-signed approval of an OAuth authorization from the wallet.
50	    pub const WALLET_CONSENT: &str = "walletConsent";
51	    /// Custos-managed hosting of an account's did:web document.
52	    pub const DID_WEB_HOSTING: &str = "didWebHosting";
53	}
54	
55	/// One host's advertised capabilities, as read from its describeServer response.
56	#[derive(Debug, Clone, Default, PartialEq, Eq, Serialize)]
57	#[serde(rename_all = "camelCase")]
58	pub struct ServerCapabilities {
59	    /// Whether the host actually answered. False means the question was never asked — no
60	    /// PDS configured, unreachable, or an unparseable response — and the empty capability
61	    /// list below carries no information.
62	    ///
63	    /// Most gates should ignore this and simply read [`has`](Self::has): "advertises
64	    /// nothing" and "could not be asked" both mean *do not offer this optional feature*,
65	    /// which degrades safely. It exists for the gates that do not merely withhold a
66	    /// feature but **tell the user something about their server** — the create-flow gate
67	    /// states that the host cannot create identities, and saying that because the network
68	    /// blinked would be a false accusation the user cannot distinguish from a real one.
69	    pub reached: bool,
70	    /// The host's self-reported Custos version, if it reported one. Informational only —
71	    /// never parsed for comparison. Gate on capability names, not on version arithmetic.
72	    pub version: Option<String>,
73	    /// Every capability name the host advertised, including ones this build does not know.
74	    /// Passing unknown names through keeps a newer server's answer intact for diagnostics.
75	    pub capabilities: Vec<String>,
76	}
77	
78	impl ServerCapabilities {
79	    /// A host that was never successfully asked: unreachable, unparseable, or not yet
80	    /// configured. Advertises nothing *and* reports `reached: false`.
81	    ///
82	    /// Distinct from a host that answered with no `custos` object — that is a real answer
83	    /// (see the [`From`] impl), and only it may be reported to the user as a fact about
84	    /// their server.
85	    pub fn none() -> Self {
86	        Self::default()
87	    }
88	
89	    /// Does this host advertise `capability`? The only question a gate should ask.
90	    pub fn has(&self, capability: &str) -> bool {
91	        self.capabilities.iter().any(|name| name == capability)
92	    }
93	
94	    /// Can a brand-new identity be created here, device key in the genesis rotation keys?
95	    /// When false, the honest offer is to *import* an identity hosted elsewhere.
96	    pub fn create_ceremony(&self) -> bool {
97	        self.has(capability::CREATE_CEREMONY)
98	    }
99	
100	    /// Will this host hold the account's encrypted recovery share and release it through
101	    /// the recovery gate? When false, recovery is entirely self-held.
102	    pub fn escrow(&self) -> bool {
103	        self.has(capability::ESCROW)
104	    }
105	
106	    /// Can a full-access session be minted from a device-key proof, with no password?
107	    /// When false, a session here needs the account's password.
108	    pub fn sovereign_sessions(&self) -> bool {
109	        self.has(capability::SOVEREIGN_SESSIONS)
110	    }
111	
112	    /// Does this host implement the auth.md agent surface?
113	    pub fn agents(&self) -> bool {
114	        self.has(capability::AGENTS)
115	    }
116	
117	    /// Can an OAuth authorization be approved with a device-key signature from the wallet?
118	    pub fn wallet_consent(&self) -> bool {
119	        self.has(capability::WALLET_CONSENT)
120	    }
121	
122	    /// Does this host serve an opted-in account's did:web document?
123	    pub fn did_web_hosting(&self) -> bool {
124	        self.has(capability::DID_WEB_HOSTING)
125	    }
126	}
127	
128	impl From<Option<&CustosExtension>> for ServerCapabilities {
129	    fn from(extension: Option<&CustosExtension>) -> Self {
130	        // Both arms describe a host that answered describeServer, so both are `reached`.
131	        // An absent `custos` object is a real answer — "this host advertises nothing", the
132	        // correct reading of every implementation that is not Custos — and must not be
133	        // conflated with never having got an answer at all.
134	        Self {
135	            reached: true,
136	            version: extension.and_then(|extension| extension.version.clone()),
137	            capabilities: extension
138	                .map(|extension| extension.capabilities.clone())
139	                .unwrap_or_default(),
140	        }
141	    }
142	}
143	
144	/// Per-host cache, keyed by [`host_key`]. Process-lifetime: a deployment's capability set
145	/// changes only when its operator reconfigures and restarts it, which is orders of
146	/// magnitude rarer than the gates that read this, and [`forget`] handles the case where
147	/// the user deliberately re-points the wallet at a host.
148	fn cache() -> &'static Mutex<HashMap<String, ServerCapabilities>> {
149	    static CACHE: OnceLock<Mutex<HashMap<String, ServerCapabilities>>> = OnceLock::new();
150	    CACHE.get_or_init(|| Mutex::new(HashMap::new()))
151	}
152	
153	/// Normalize a PDS base URL into a cache key, so `https://Pds.Example.com/` and
154	/// `https://pds.example.com` are one host rather than two entries that can disagree.
155	fn host_key(pds_url: &str) -> String {
156	    pds_url.trim().trim_end_matches('/').to_ascii_lowercase()
157	}
158	
159	/// Record what a host advertised. Called from every successful `describe_server`, so the
160	/// cache warms from calls the wallet was making anyway.
161	pub fn record(pds_url: &str, extension: Option<&CustosExtension>) {
162	    let capabilities = ServerCapabilities::from(extension);
163	    tracing::debug!(
164	        pds_url = %pds_url,
165	        version = ?capabilities.version,
166	        capabilities = ?capabilities.capabilities,
167	        "recorded host capabilities"
168	    );
169	    if let Ok(mut cache) = cache().lock() {
170	        cache.insert(host_key(pds_url), capabilities);
171	    }
172	}
173	
174	/// What this host advertised the last time it was described, if it has been described.
175	pub fn cached(pds_url: &str) -> Option<ServerCapabilities> {
176	    cache()
177	        .lock()
178	        .ok()
179	        .and_then(|cache| cache.get(&host_key(pds_url)).cloned())
180	}
181	
182	/// Drop every cached answer. Tests share one process (and httpmock reuses server ports across
183	/// tests), so a verdict recorded for one test's mock host can otherwise be read by a later test
184	/// that happens to be handed the same address.
185	#[cfg(test)]
186	pub fn clear_for_test() {
187	    if let Ok(mut cache) = cache().lock() {
188	        cache.clear();
189	    }
190	}
191	
192	/// Drop a host's cached answer, forcing the next [`probe`] to re-ask. Called when the user
193	/// re-points the wallet at a PDS, so a re-configured (or newly reachable) host is re-read.
194	pub fn forget(pds_url: &str) {
195	    if let Ok(mut cache) = cache().lock() {
196	        cache.remove(&host_key(pds_url));
197	    }
198	}
199	
200	/// The cached capabilities for `pds_url`, describing the server once if it has not been
201	/// described yet.
202	///
203	/// A host that cannot be reached, or whose response cannot be parsed, yields
204	/// [`ServerCapabilities::none`] and is **not** cached — the answer is "we could not ask",
205	/// and caching it would freeze a transient outage into a permanent verdict. Callers gating
206	/// optional features degrade to standard-lexicon behavior, which is safe; a caller that
207	/// must distinguish "unreachable" from "not offered" reads
208	/// [`ServerCapabilities::reached`], which is false in exactly that case.
209	pub async fn probe(client: &PdsClient, pds_url: &str) -> ServerCapabilities {
210	    if let Some(cached) = cached(pds_url) {
211	        return cached;
212	    }
213	
214	    match client.describe_server(pds_url).await {
215	        // `describe_server` records into the cache on success; re-read it so this returns
216	        // exactly what was stored rather than a parallel copy.
217	        Ok(_) => cached(pds_url).unwrap_or_else(ServerCapabilities::none),
218	        Err(e) => {
219	            tracing::warn!(
220	                pds_url = %pds_url,
221	                error = %e,
222	                "capability probe failed; treating host as advertising nothing"
223	            );
224	            ServerCapabilities::none()
225	        }
226	    }
227	}
