229	#[cfg(test)]
230	mod tests {
231	    use super::*;
232	
233	    fn extension(version: &str, capabilities: &[&str]) -> CustosExtension {
234	        CustosExtension {
235	            version: Some(version.to_string()),
236	            capabilities: capabilities.iter().map(|c| c.to_string()).collect(),
237	        }
238	    }
239	
240	    #[test]
241	    fn absent_extension_means_no_capabilities() {
242	        let capabilities = ServerCapabilities::from(None::<&CustosExtension>);
243	        // Every capability is withheld, but the host DID answer — so this is not the same
244	        // value as `none()`, which means the question was never put to it. Only this one
245	        // may be reported to the user as a fact about their server.
246	        assert!(capabilities.reached);
247	        assert_ne!(capabilities, ServerCapabilities::none());
248	        assert!(!ServerCapabilities::none().reached);
249	        assert!(!capabilities.create_ceremony());
250	        assert!(!capabilities.escrow());
